import { useId } from "react";
import type { ReactElement } from "react";
import "./ProblemTable.css";

export interface ProblemRow {
  title: string;
  pattern: string;
  minutes: number;
  review: string;
  due: boolean;
}

export interface ProblemTableProps {
  rows: readonly ProblemRow[];
}

export function ProblemTable({ rows }: ProblemTableProps): ReactElement {
  const captionId = useId();

  return (
    <div className="problem-table" role="region" aria-labelledby={captionId} tabIndex={0}>
      <table className="problem-table__table">
        <caption id={captionId} className="sr-only">
          Solved problems
        </caption>
        <thead>
          <tr>
            <th scope="col">Title</th>
            <th scope="col">Pattern</th>
            <th scope="col" className="problem-table__num">Minutes</th>
            <th scope="col">Next review</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.title}>
              <td>{row.title}</td>
              <td>{row.pattern}</td>
              <td className="problem-table__num">{row.minutes}</td>
              <td className={row.due ? "problem-table__review is-due" : "problem-table__review"}>
                {row.review}
                {row.due ? <span className="problem-table__due">Due today</span> : null}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
```

